"""Compare the decomposed path against the forced fallback path."""
import json, sys, copy
sys.path.insert(0, '/workspace/submission')
sys.path.insert(0, '/workspace/dev')
import analyze, infer, gen, genbig
from instance import parse_request


def body_of(x, force_full):
    inst = parse_request(json.loads(json.dumps(x)))
    if force_full:
        old = infer.PATTERN_CAP
        infer.PATTERN_CAP = -1
        try:
            eng = infer._Engine(inst)
            try:
                return eng.run()
            except infer.Infeasible:
                return {'status': 'infeasible'}
        finally:
            infer.PATTERN_CAP = old
    else:
        try:
            return infer.analyze(inst)
        except infer.Infeasible:
            return {'status': 'infeasible'}


def compare(x):
    a = body_of(x, False)
    b = body_of(x, True)
    if a.get('status') == 'infeasible' or b.get('status') == 'infeasible':
        return [] if a.get('status') == b.get('status') else ['infeasible mismatch %s/%s' % (a.get('status'), b.get('status'))']
    problems = []
    for key in ('status', 'min_faults'):
        if a.get(key) != b.get(key):
            problems.append('%s %r != %r' % (key, a.get(key), b.get(key)))
    if {k: sorted(v) for k, v in a['faults'].items()} != {k: sorted(v) for k, v in b['faults'].items()}:
        problems.append('faults %r != %r' % (a['faults'], b['faults']))
    for i, (sa, sb) in enumerate(zip(a['snapshots'], b['snapshots'])):
        for key in ('id', 'demands', 'links', 'verdict'):
            if sa.get(key) != sb.get(key):
                problems.append('snapshots[%d].%s %r != %r' % (i, key, sa.get(key), sb.get(key)))
    return problems


def main():
    bad = 0
    n = 0
    for seed in range(int(sys.argv[1]), int(sys.argv[1]) + int(sys.argv[2])):
        x = gen.gen_instance(seed)
        if x is None:
            continue
        try:
            problems = compare(x)
        except Exception as exc:
            import traceback
            traceback.print_exc()
            print('CRASH seed=%d' % seed)
            bad += 1
            continue
        n += 1
        if problems:
            bad += 1
            print('MISMATCH seed=%d: %s' % (seed, '; '.join(problems[:3])))
            if bad > 4:
                break
    print('compared %d, bad=%d' % (n, bad))


main()
